local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "chlen"
Junkie.identifier = "1072682"
Junkie.provider = "chlen"

getgenv().SCRIPT_KEY = "ez"
local _oldCheck = Junkie.check_key
Junkie.check_key = function(key)
    if key == "ez" then
        return {valid = true, message = "KEY_VALID"}
    end
    return _oldCheck(key)
end

